<?php
namespace App\Http\Controllers; use App\Models\Folio; use App\Services\Folios\FolioService; use Illuminate\Http\Request;
class FolioController extends Controller { public function addCharge(Request $r,Folio $folio,FolioService $svc){abort_unless($folio->property_id===$r->user()->property_id,404);$d=$r->validate(['department'=>'required|max:50','description'=>'required|max:255','quantity'=>'required|numeric|min:0.001','unit_price'=>'required|numeric|min:0','tax_amount'=>'nullable|numeric|min:0']);$svc->addCharge($folio,$d,$r->user()->id);return back()->with('success','Charge posted to folio.');} public function payment(Request $r,Folio $folio,FolioService $svc){abort_unless($folio->property_id===$r->user()->property_id,404);$d=$r->validate(['method'=>'required|in:cash,mtn_momo,airtel_money,pesapal,flutterwave,bank_transfer,card,cheque','amount'=>'required|numeric|min:1','payer_phone'=>'nullable|max:50','gateway_reference'=>'nullable|max:120','description'=>'nullable|max:255']);$svc->recordPayment($folio,$d,$r->user()->id);return back()->with('success','Payment recorded successfully.');} public function invoice(Request $r,Folio $folio,FolioService $svc){abort_unless($folio->property_id===$r->user()->property_id,404);$folio=$svc->recalculate($folio);$folio->load(['property','guest','reservation.rooms.room','items','payments']);return view('documents.invoice',compact('folio'));} public function receipt(Request $r,Folio $folio,FolioService $svc){abort_unless($folio->property_id===$r->user()->property_id,404);$folio=$svc->recalculate($folio);$folio->load(['property','guest','reservation.rooms.room','payments']);return view('documents.receipt',compact('folio'));} }
